# Pulumi ComponentResource: App Infrastructure

## Project Structure

```
pulumi-infra/
├── Pulumi.yaml
├── Pulumi.dev.yaml
├── Pulumi.prod.yaml
├── index.ts
├── package.json
├── tsconfig.json
└── components/
    └── app-infra.ts
```

## Configuration Files

### `Pulumi.yaml`

```yaml
name: app-infra
runtime: nodejs
description: Stateless web app infrastructure with S3, RDS, and IAM
```

### `Pulumi.dev.yaml`

```yaml
config:
  aws:region: us-east-1
  app-infra:environment: dev
  app-infra:dbInstanceClass: db.t3.micro
  app-infra:dbMultiAz: "false"
  app-infra:dbAllocatedStorage: "20"
  app-infra:enableReplication: "false"
  app-infra:dbPassword:
    secure: AAABAFx7...  # pulumi config set --secret dbPassword
```

### `Pulumi.prod.yaml`

```yaml
config:
  aws:region: us-east-1
  app-infra:environment: prod
  app-infra:dbInstanceClass: db.t3.medium
  app-infra:dbMultiAz: "true"
  app-infra:dbAllocatedStorage: "100"
  app-infra:enableReplication: "true"
  app-infra:replicationRegion: us-west-2
  app-infra:dbPassword:
    secure: AAABAGk2...  # pulumi config set --secret dbPassword
```

## Component Resource

### `components/app-infra.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

export interface AppInfraArgs {
    environment: pulumi.Input<string>;
    dbInstanceClass: pulumi.Input<string>;
    dbMultiAz: pulumi.Input<boolean>;
    dbAllocatedStorage: pulumi.Input<number>;
    dbPassword: pulumi.Input<string>;
    enableReplication: pulumi.Input<boolean>;
    replicationRegion?: pulumi.Input<string>;
    tags?: pulumi.Input<{ [key: string]: pulumi.Input<string> }>;
}

export class AppInfra extends pulumi.ComponentResource {
    public readonly bucket: aws.s3.BucketV2;
    public readonly bucketReplicationBucket?: aws.s3.BucketV2;
    public readonly dbInstance: aws.rds.Instance;
    public readonly dbSubnetGroup: aws.rds.SubnetGroup;
    public readonly serviceRole: aws.iam.Role;
    public readonly servicePolicy: aws.iam.Policy;
    public readonly dbSecurityGroup: aws.ec2.SecurityGroup;
    public readonly connectionStringSecret: aws.secretsmanager.Secret;
    public readonly connectionStringSecretVersion: aws.secretsmanager.SecretVersion;

    constructor(
        name: string,
        args: AppInfraArgs,
        opts?: pulumi.ComponentResourceOptions,
    ) {
        super("custom:infra:AppInfra", name, {}, opts);

        const defaultTags = {
            Environment: args.environment,
            ManagedBy: "pulumi",
            Component: name,
        };
        const tags = pulumi.all([args.tags, defaultTags]).apply(
            ([custom, defaults]) => ({ ...defaults, ...custom }),
        );

        // ── S3 Bucket ────────────────────────────────────────────────

        this.bucket = new aws.s3.BucketV2(`${name}-assets`, {
            tags: pulumi.output(tags).apply(t => ({
                ...t,
                Name: `${name}-assets`,
            })),
        }, { parent: this });

        new aws.s3.BucketVersioningV2(`${name}-assets-versioning`, {
            bucket: this.bucket.id,
            versioningConfiguration: {
                status: "Enabled",
            },
        }, { parent: this });

        new aws.s3.BucketServerSideEncryptionConfigurationV2(
            `${name}-assets-encryption`,
            {
                bucket: this.bucket.id,
                rules: [{
                    applyServerSideEncryptionByDefault: {
                        sseAlgorithm: "AES256",
                    },
                    bucketKeyEnabled: true,
                }],
            },
            { parent: this },
        );

        new aws.s3.BucketPublicAccessBlock(`${name}-assets-pab`, {
            bucket: this.bucket.id,
            blockPublicAcls: true,
            blockPublicPolicy: true,
            ignorePublicAcls: true,
            restrictPublicBuckets: true,
        }, { parent: this });

        // Cross-region replication (prod only)
        const enableRepl = pulumi.output(args.enableReplication);
        if (enableRepl.apply(e => e)) {
            const replRegion = args.replicationRegion || "us-west-2";

            const replProvider = new aws.Provider(`${name}-repl-provider`, {
                region: replRegion as aws.Region,
            }, { parent: this });

            this.bucketReplicationBucket = new aws.s3.BucketV2(
                `${name}-assets-replica`,
                {
                    tags: pulumi.output(tags).apply(t => ({
                        ...t,
                        Name: `${name}-assets-replica`,
                    })),
                },
                { parent: this, provider: replProvider },
            );

            new aws.s3.BucketVersioningV2(`${name}-replica-versioning`, {
                bucket: this.bucketReplicationBucket.id,
                versioningConfiguration: { status: "Enabled" },
            }, { parent: this, provider: replProvider });

            new aws.s3.BucketServerSideEncryptionConfigurationV2(
                `${name}-replica-encryption`,
                {
                    bucket: this.bucketReplicationBucket.id,
                    rules: [{
                        applyServerSideEncryptionByDefault: {
                            sseAlgorithm: "AES256",
                        },
                    }],
                },
                { parent: this, provider: replProvider },
            );

            const replRole = new aws.iam.Role(`${name}-repl-role`, {
                assumeRolePolicy: JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [{
                        Action: "sts:AssumeRole",
                        Effect: "Allow",
                        Principal: { Service: "s3.amazonaws.com" },
                    }],
                }),
                tags,
            }, { parent: this });

            new aws.iam.RolePolicy(`${name}-repl-policy`, {
                role: replRole.id,
                policy: pulumi.all([this.bucket.arn, this.bucketReplicationBucket.arn])
                    .apply(([srcArn, dstArn]) => JSON.stringify({
                        Version: "2012-10-17",
                        Statement: [
                            {
                                Action: ["s3:GetReplicationConfiguration", "s3:ListBucket"],
                                Effect: "Allow",
                                Resource: srcArn,
                            },
                            {
                                Action: ["s3:GetObjectVersionForReplication", "s3:GetObjectVersionAcl"],
                                Effect: "Allow",
                                Resource: `${srcArn}/*`,
                            },
                            {
                                Action: ["s3:ReplicateObject", "s3:ReplicateDelete"],
                                Effect: "Allow",
                                Resource: `${dstArn}/*`,
                            },
                        ],
                    })),
            }, { parent: this });

            new aws.s3.BucketReplicationConfig(`${name}-repl-config`, {
                bucket: this.bucket.id,
                role: replRole.arn,
                rules: [{
                    id: "replicate-all",
                    status: "Enabled",
                    destination: {
                        bucket: this.bucketReplicationBucket.arn,
                        storageClass: "STANDARD",
                    },
                }],
            }, { parent: this, dependsOn: [this.bucketReplicationBucket] });
        }

        // ── RDS PostgreSQL ───────────────────────────────────────────

        const vpc = aws.ec2.getVpcOutput({ default: true });
        const subnets = aws.ec2.getSubnetsOutput({
            filters: [{ name: "vpc-id", values: [vpc.id] }],
        });

        this.dbSecurityGroup = new aws.ec2.SecurityGroup(`${name}-db-sg`, {
            vpcId: vpc.id,
            description: `RDS security group for ${name}`,
            ingress: [{
                protocol: "tcp",
                fromPort: 5432,
                toPort: 5432,
                cidrBlocks: ["10.0.0.0/8"],
                description: "PostgreSQL from internal",
            }],
            egress: [{
                protocol: "-1",
                fromPort: 0,
                toPort: 0,
                cidrBlocks: ["0.0.0.0/0"],
            }],
            tags: pulumi.output(tags).apply(t => ({
                ...t,
                Name: `${name}-db-sg`,
            })),
        }, { parent: this });

        this.dbSubnetGroup = new aws.rds.SubnetGroup(`${name}-db-subnets`, {
            subnetIds: subnets.ids,
            tags: pulumi.output(tags).apply(t => ({
                ...t,
                Name: `${name}-db-subnets`,
            })),
        }, { parent: this });

        this.dbInstance = new aws.rds.Instance(`${name}-db`, {
            engine: "postgres",
            engineVersion: "16.3",
            instanceClass: args.dbInstanceClass,
            allocatedStorage: args.dbAllocatedStorage,
            dbName: pulumi.interpolate`appdb_${args.environment}`,
            username: "appadmin",
            password: args.dbPassword,
            dbSubnetGroupName: this.dbSubnetGroup.name,
            vpcSecurityGroupIds: [this.dbSecurityGroup.id],
            multiAz: args.dbMultiAz,
            storageEncrypted: true,
            deletionProtection: true,
            backupRetentionPeriod: 14,
            backupWindow: "03:00-04:00",
            maintenanceWindow: "sun:05:00-sun:06:00",
            skipFinalSnapshot: false,
            finalSnapshotIdentifier: pulumi.interpolate`${name}-db-final-${args.environment}`,
            publiclyAccessible: false,
            autoMinorVersionUpgrade: true,
            tags: pulumi.output(tags).apply(t => ({
                ...t,
                Name: `${name}-db`,
            })),
        }, { parent: this });

        // ── DB Connection String Secret ──────────────────────────────

        this.connectionStringSecret = new aws.secretsmanager.Secret(
            `${name}-db-conn`,
            {
                description: `Database connection string for ${name} (${args.environment})`,
                tags,
            },
            { parent: this },
        );

        this.connectionStringSecretVersion = new aws.secretsmanager.SecretVersion(
            `${name}-db-conn-version`,
            {
                secretId: this.connectionStringSecret.id,
                secretString: pulumi.interpolate`postgresql://appadmin:${args.dbPassword}@${this.dbInstance.endpoint}/${this.dbInstance.dbName}`,
            },
            { parent: this },
        );

        // ── IAM Role for Service Accounts ────────────────────────────

        const isProd = pulumi.output(args.environment).apply(e => e === "prod");

        const assumeRolePolicy = isProd.apply(prod => {
            if (prod) {
                // Prod: OIDC trust for IRSA (IAM Roles for Service Accounts)
                return pulumi.interpolate`{
                    "Version": "2012-10-17",
                    "Statement": [{
                        "Effect": "Allow",
                        "Principal": {
                            "Federated": "arn:aws:iam::\${data.aws_caller_identity.current.account_id}:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLE"
                        },
                        "Action": "sts:AssumeRoleWithWebIdentity",
                        "Condition": {
                            "StringEquals": {
                                "oidc.eks.us-east-1.amazonaws.com/id/EXAMPLE:sub": "system:serviceaccount:default:${name}-sa"
                            }
                        }
                    }]
                }`;
            }
            // Dev: broader assume role for programmatic access
            return JSON.stringify({
                Version: "2012-10-17",
                Statement: [{
                    Effect: "Allow",
                    Principal: { Service: "ec2.amazonaws.com" },
                    Action: "sts:AssumeRole",
                }],
            });
        });

        this.serviceRole = new aws.iam.Role(`${name}-svc-role`, {
            assumeRolePolicy: assumeRolePolicy,
            tags: pulumi.output(tags).apply(t => ({
                ...t,
                Name: `${name}-svc-role`,
            })),
        }, { parent: this });

        // Least-privilege policy: scoped to the specific bucket and secret
        const policyDocument = pulumi.all([
            this.bucket.arn,
            this.connectionStringSecret.arn,
            isProd,
        ]).apply(([bucketArn, secretArn, prod]) => {
            const s3Actions = prod
                ? [
                    "s3:GetObject",
                    "s3:PutObject",
                    "s3:DeleteObject",
                    "s3:ListBucket",
                    "s3:GetBucketVersioning",
                ]
                : [
                    "s3:GetObject",
                    "s3:PutObject",
                    "s3:DeleteObject",
                    "s3:ListBucket",
                    "s3:GetBucketVersioning",
                    "s3:ListBucketVersions",
                    "s3:DeleteObjectVersion",
                ];

            return JSON.stringify({
                Version: "2012-10-17",
                Statement: [
                    {
                        Sid: "BucketAccess",
                        Effect: "Allow",
                        Action: s3Actions,
                        Resource: [bucketArn, `${bucketArn}/*`],
                    },
                    {
                        Sid: "SecretAccess",
                        Effect: "Allow",
                        Action: [
                            "secretsmanager:GetSecretValue",
                            "secretsmanager:DescribeSecret",
                        ],
                        Resource: secretArn,
                    },
                ],
            });
        });

        this.servicePolicy = new aws.iam.Policy(`${name}-svc-policy`, {
            policy: policyDocument,
            tags,
        }, { parent: this });

        new aws.iam.RolePolicyAttachment(`${name}-svc-attach`, {
            role: this.serviceRole.name,
            policyArn: this.servicePolicy.arn,
        }, { parent: this });

        // Register outputs
        this.registerOutputs({
            bucketName: this.bucket.id,
            bucketArn: this.bucket.arn,
            dbEndpoint: this.dbInstance.endpoint,
            dbArn: this.dbInstance.arn,
            serviceRoleArn: this.serviceRole.arn,
            secretArn: this.connectionStringSecret.arn,
        });
    }
}
```

## Entry Point

### `index.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";
import { AppInfra } from "./components/app-infra";

const config = new pulumi.Config();

const environment = config.require("environment");
const dbPassword = config.requireSecret("dbPassword");

const infra = new AppInfra("app", {
    environment,
    dbInstanceClass: config.require("dbInstanceClass"),
    dbMultiAz: config.getBoolean("dbMultiAz") ?? false,
    dbAllocatedStorage: config.getNumber("dbAllocatedStorage") ?? 20,
    dbPassword,
    enableReplication: config.getBoolean("enableReplication") ?? false,
    replicationRegion: config.get("replicationRegion"),
    tags: {
        Project: "app-infra",
        Team: "platform",
    },
});

export const bucketName = infra.bucket.id;
export const bucketArn = infra.bucket.arn;
export const dbEndpoint = infra.dbInstance.endpoint;
export const serviceRoleArn = infra.serviceRole.arn;
export const secretArn = infra.connectionStringSecret.arn;
```

